try{const raw=localStorage.getItem(KEY);if(raw)save=parseSave(raw);}catch(e){storageError=true;}
const fmt=(v,d=2)=>Number(v).toFixed(d),pct=v=>`${fmt(v*100,1)}%`,state=()=>save.states[save.current],signed=v=>(v>0?'+':'')+v;
const svg=(content,view='0 0 440 260')=>`<svg class="svg-stage" viewBox="${view}" aria-hidden="true">${content}</svg>`;
function store(){try{localStorage.setItem(KEY,JSON.stringify(save));}catch{if(!storageError){toast('浏览器未允许本机保存，请通过“存档”导出进度。');storageError=true;}}}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4000);}
function beep(win=false){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();[0,...(win?[.12,.24]:[])].forEach((offset,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=win?[392,523,659][i]:260;g.gain.setValueAtTime(.05,audio.currentTime+offset);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+offset+.25);o.connect(g).connect(audio.destination);o.start(audio.currentTime+offset);o.stop(audio.currentTime+offset+.26);});}catch{}}
